package com.dawnyew.protocol

import com.dawnyew.core.*
import kotlinx.serialization.json.*
import kotlin.test.*

/** Frozen v1 bytes from the original nine-entity schema, not generated by the current writer. */
class BackupVersionCompatibilityTest {
    private val bytes = """{"canonicalizationVersion":1,"counts":{"budgets":"0","categories":"1","deletionGroups":"0","entries":"1","importBatches":"0","importMembers":"0","ledgers":"1","preferences":"0","sourceIdentities":"0"},"createdAt":"2026-10-18T04:00:00Z","datasetId":"00000000-0000-4000-8000-000000000001","format":"dawnyew-backup","formatVersion":1,"records":{"budgets":[],"categories":[{"direction":"EXPENSE","enabled":true,"id":"00000000-0000-4000-8000-000000000003","ledgerId":"00000000-0000-4000-8000-000000000002","name":"餐饮","revision":"1","sortOrder":0}],"deletionGroups":[],"entries":[{"amountMinor":"12345","captureEngineVersion":null,"captureFingerprint":null,"categoryId":"00000000-0000-4000-8000-000000000003","createdAt":"2026-10-18T04:00:00Z","creationOperationId":"00000000-0000-4000-8000-000000000005","deletionGroupId":null,"id":"00000000-0000-4000-8000-000000000004","kind":"EXPENSE","ledgerId":"00000000-0000-4000-8000-000000000002","note":"旧数据🧾","occurrence":"2026-10-17T12:34:56","originKind":"MANUAL","parentExpenseId":null,"revision":"1","updatedAt":"2026-10-18T04:00:00Z"}],"importBatches":[],"importMembers":[],"ledgers":[{"archived":false,"currency":"CNY","id":"00000000-0000-4000-8000-000000000002","name":"旧账本","revision":"1","sortOrder":0}],"preferences":[],"sourceIdentities":[]},"sha256":"bce9cdedc3c222fa3f1f570e0a38be3d55701b67c1ca5ac58cf9426b40efe4dc"}"""
    private fun oldDocument(): BackupDocument {
        val root=Json.parseToJsonElement(bytes).jsonObject
        return BackupDocument(root.getValue("datasetId").jsonPrimitive.content,root.getValue("createdAt").jsonPrimitive.content,
            root.getValue("records").jsonObject.mapValues { (_,v)->v.jsonArray.map { it.jsonObject } },
            root.getValue("counts").jsonObject.mapValues { (_,v)->v.jsonPrimitive.content.toLong() },
            root.getValue("sha256").jsonPrimitive.content,formatVersion=1)
    }
    @Test fun frozenOldBytesKeepTheirOriginalNineTypeDigestAndFields() {
        val old=oldDocument()
        assertEquals("bce9cdedc3c222fa3f1f570e0a38be3d55701b67c1ca5ac58cf9426b40efe4dc",BackupProtocol.digest(old))
        val restored=BackupProtocol.restore(old)
        assertEquals(12345L,restored.entries.single().amountMinor)
        assertEquals("旧数据🧾",restored.entries.single().note)
        assertTrue(restored.receipts.isEmpty())
    }
    @Test fun newWriterUsesVersionTwoAndIncludesAllFinancialEntityCollections() {
        val upgraded=BackupProtocol.create(BackupProtocol.restore(oldDocument()),"2026-10-24T04:00:00Z")
        assertEquals(2,upgraded.formatVersion)
        assertEquals(23,upgraded.records.size)
        assertEquals(23,upgraded.counts.size)
        assertEquals(1,upgraded.canonicalizationVersion)
    }
    @Test fun oldVersionCannotClaimNewEntityEvenWithARecomputedHash() {
        val old=oldDocument()
        val changed=old.copy(records=old.records+("accounts" to emptyList()),counts=old.counts+("accounts" to 0L))
        assertFails { BackupProtocol.restore(changed.copy(sha256=BackupProtocol.digest(changed))) }
    }
}
